class TwoSum:
    def __init__(self):
        self.count = defaultdict(int)            # value -> how many times it was added

    def add(self, number: int) -> None:
        self.count[number] += 1

    def find(self, value: int) -> bool:
        for num, c in self.count.items():        # loop over the distinct numbers
            other = value - num
            if other in self.count and (other != num or c > 1):   # a number cannot pair with itself unless added twice
                return True
        return False
